import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
public class PatchBodies implements Opcodes{
 static void replace(MethodNode m,String owner){m.instructions.clear();m.tryCatchBlocks.clear();if(m.localVariables!=null)m.localVariables.clear();int slot=0;for(Type t:Type.getArgumentTypes(m.desc)){m.instructions.add(new VarInsnNode(t.getOpcode(ILOAD),slot));slot+=t.getSize();}m.instructions.add(new MethodInsnNode(INVOKESTATIC,owner,"render",m.desc,false));m.instructions.add(new InsnNode(RETURN));}
 static MethodNode scope(ClassNode n,MethodNode m){String old=m.name;m.name=old+"BodyUnpooled";m.access=ACC_PRIVATE|ACC_STATIC;MethodNode w=new MethodNode(ASM9,ACC_PUBLIC|ACC_STATIC,old,m.desc,null,null);InsnList x=w.instructions;x.add(new MethodInsnNode(INVOKESTATIC,"cn/judgfire/BodyScratch","begin","()V",false));LabelNode a=new LabelNode(),b=new LabelNode(),h=new LabelNode();x.add(a);int slot=0;for(Type t:Type.getArgumentTypes(m.desc)){x.add(new VarInsnNode(t.getOpcode(ILOAD),slot));slot+=t.getSize();}x.add(new MethodInsnNode(INVOKESTATIC,n.name,m.name,m.desc,false));x.add(b);x.add(new MethodInsnNode(INVOKESTATIC,"cn/judgfire/BodyScratch","end","()V",false));x.add(new InsnNode(RETURN));x.add(h);x.add(new FrameNode(F_SAME1,0,null,1,new Object[]{"java/lang/Throwable"}));x.add(new VarInsnNode(ASTORE,slot));x.add(new MethodInsnNode(INVOKESTATIC,"cn/judgfire/BodyScratch","end","()V",false));x.add(new VarInsnNode(ALOAD,slot));x.add(new InsnNode(ATHROW));w.tryCatchBlocks.add(new TryCatchBlockNode(a,b,h,null));return w;}
 static void gate(MethodNode m,String key,boolean handled){InsnList x=new InsnList();x.add(new LdcInsnNode(key));x.add(new MethodInsnNode(INVOKESTATIC,"cn/judgfire/RenderOptions","enabled","(Ljava/lang/String;)Z",false));LabelNode yes=new LabelNode();x.add(new JumpInsnNode(IFNE,yes));if(handled){x.add(new InsnNode(ICONST_1));x.add(new InsnNode(IRETURN));}else x.add(new InsnNode(RETURN));x.add(yes);x.add(new FrameNode(F_SAME,0,null,0,null));m.instructions.insert(x);}
 public static void main(String[]args)throws Exception{Path out=Path.of(args[1]);int changes=0;try(var z=new JarFile(args[0])){for(String name:List.of("cn/judgfire/OriginalMotion","cn/punishmenteye/WeaponVisuals","cn/punishmenteye/SkinVisuals","cn/punishmenteye/MuzzleVisuals","cn/punishmenteye/TierEyeEffects","cn/judgfire/NativeSkinAbsorb","cn/judgfire/NativeSkinFlow","cn/judgfire/NativeSkinBodyBridge")){
  var r=new ClassReader(z.getInputStream(z.getJarEntry(name+".class")));var n=new ClassNode();r.accept(n,0);var add=new ArrayList<MethodNode>();for(var m:n.methods){
   if(name.endsWith("OriginalMotion")&&m.name.equals("render")&&m.desc.startsWith("(Lcn/judgfire/MotionSkin$Mesh;")){replace(m,"cn/judgfire/GunMeshRender");changes++;}
   if(name.endsWith("WeaponVisuals")&&m.name.equals("render")){replace(m,"cn/punishmenteye/EyeBodyRender");changes++;}
   if(name.endsWith("WeaponVisuals")&&m.name.equals("reload")){m.instructions.insert(new MethodInsnNode(INVOKESTATIC,"cn/punishmenteye/EffectScratch","clear","()V",false));m.instructions.insert(new MethodInsnNode(INVOKESTATIC,"cn/punishmenteye/EyeBodyRender","clear","()V",false));}
   if(name.endsWith("OriginalMotion")&&m.name.equals("reload")){m.instructions.insert(new MethodInsnNode(INVOKESTATIC,"cn/judgfire/GunMeshRender","clear","()V",false));}
   if(name.endsWith("NativeSkinAbsorb")&&m.name.equals("render")){add.add(scope(n,m));changes++;}
   if(name.endsWith("NativeSkinFlow")&&m.name.equals("render")){gate(m,"render.fire_flow",false);changes++;}
   if(name.endsWith("NativeSkinBodyBridge")&&m.name.equals("body")){gate(m,"render.fire_surface",true);changes++;}
   if((name.endsWith("SkinVisuals")||name.endsWith("MuzzleVisuals"))&&m.name.equals("renderEffects")){gate(m,"render.eye_effects",false);changes++;}
   if(name.endsWith("TierEyeEffects")&&m.name.equals("renderEffect")){gate(m,"render.eye_effects",false);changes++;}
   for(var i:m.instructions)if(i instanceof MethodInsnNode call&&call.owner.equals("cn/punishmenteye/MuzzleParticles")&&call.name.equals("render")){call.name="renderEffect";changes++;}
  }n.methods.addAll(add);var w=new ClassWriter(r,ClassWriter.COMPUTE_MAXS);n.accept(w);Path p=out.resolve(name+".class");Files.createDirectories(p.getParent());Files.write(p,w.toByteArray());
 }}if(changes<7)throw new AssertionError(changes);System.out.println("PASS narrow body hooks "+changes);}
}
